    return try FfiConverterTypeAppIa.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeAppIa_lower(_ value: AppIa) -> UInt64 {
    return FfiConverterTypeAppIa.lower(value)
}






