#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeDocumentoReflujo: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = DocumentoReflujo

    public static func lift(_ handle: UInt64) throws -> DocumentoReflujo {
        return DocumentoReflujo(unsafeFromHandle: handle)
    }

    public static func lower(_ value: DocumentoReflujo) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DocumentoReflujo {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: DocumentoReflujo, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeDocumentoReflujo_lift(_ handle: UInt64) throws -> DocumentoReflujo {
    return try FfiConverterTypeDocumentoReflujo.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeDocumentoReflujo_lower(_ value: DocumentoReflujo) -> UInt64 {
    return FfiConverterTypeDocumentoReflujo.lower(value)
}






/**
 * **Un lienzo abierto para editar.** Se usa desde varios hilos: el puntero
 * y el pintado desde el principal, guardar desde uno de fondo.
 */
public protocol EditorLienzoProtocol: AnyObject, Sendable {
    
    /**
     * **La tinta del anotador de pantalla**, resumida: su huella y la caja
     * de cada trazo (en el mundo del lienzo). Sin texto a medias: quien
     * llama lo termina antes (`terminar_texto`).
     */
    func tintaDePantalla()  -> TintaDePantalla
    
    /**
     * Su ventana paso al frente: lo que dibuje el asistente viene aqui.
     */
    func alFrente() 
    
    /**
     * **La variante de 90 grados** del angulo: pulsar su atajo con el
     * angulo ya en la mano pasa del cuadradito a la letra griega y al
     * reves (Windows, `dibujo/mano.rs`). Devuelve si queda el cuadradito.
     */
    func alternarAnguloRecto()  -> Bool
    
    /**
     * **Si lo de encima se mueve solo** (la estela del laser, que se apaga
     * sola): mientras diga que si, Swift repinta a cada fotograma aunque la
     * version no cambie.
     */
    func animando()  -> Bool
    
    /**
     * Borra lo elegido, en un paso. `false` si no habia nada elegido.
     */
    func borrarSeleccion()  -> Bool
    
    /**
     * La caja de lo dibujado, para encajar la vista. `None` si esta vacio.
     */
    func caja()  -> CajaLienzo?
    
    /**
     * **Donde esta el cursor del texto** que se escribe, en el mundo (una
     * raya vertical del alto del renglon). Para colocar la ventanita del
     * metodo de entrada (`firstRect(forCharacterRange:)`). `None` si no se
     * escribe.
     */
    func cajaDelCursor()  -> CajaLienzo?
    
    /**
     * **Calibra**: la raya de `largo_px` (lo que dio
     * [`PeticionLienzo::Calibrar`]) mide `valor` `unidad` de verdad. Desde
     * ahora todas las cotas del lienzo hablan en esa unidad. Un paso de
     * deshacer; `false` si la medida no puede ser cierta (no toca nada).
     */
    func calibrar(largoPx: Float, valor: Float, unidad: String)  -> Bool
    
    /**
     * **La letra griega de la marca de angulo recien puesta** (o de la
     * unica elegida): `paso` > 0 la siguiente libre, < 0 la anterior, en
     * un paso de deshacer. Es lo que hacen las flechas arriba y abajo con
     * el angulo en la mano en Windows (`dibujo/mano.rs`). `false` si no
     * habia marca o no cambio.
     */
    func cambiarLetraDeAngulo(paso: Int32)  -> Bool
    
    /**
     * Sube con cada cambio del DOCUMENTO (para guardar solo, con calma).
     */
    func cambios()  -> UInt64
    
    /**
     * Su ventana se cerro: el asistente ya no dibuja aqui.
     */
    func cerrado() 
    
    /**
     * Cuantos elementos hay elegidos (para la barra y las pruebas).
     */
    func cuantosElegidos()  -> UInt64
    
    /**
     * Cuantos elementos visibles tiene.
     */
    func cuantosElementos()  -> UInt64
    
    /**
     * Deshace el ultimo paso (no a mitad de un gesto).
     */
    func deshacer()  -> Bool
    
    /**
     * **Aplica lo dictado a la cota `id`**: el largo en la unidad de la
     * escala (o en pixeles sin ella) y el angulo como en un plano (0 a la
     * derecha, 90 hacia arriba). Un paso de deshacer; `false` si no cambio.
     */
    func dictarCota(id: UInt64, largo: Float, grados: Float)  -> Bool
    
    /**
     * Si es la tinta de una hoja de un documento (ver
     * [`Nucleo::anotar_hoja`]).
     */
    func esDeDocumento()  -> Bool
    
    /**
     * **Anotando un plano**: lo que nace (o cambia de grosor o letra desde
     * el panel) con los tamanos de fabrica se pone a `k` (uno entre el zoom
     * con que se ve el plano): un trazo «fino» se ve fino en la pantalla,
     * como en Windows y Android. Lo que ya estaba no se toca.
     */
    func escalaDeLoNuevo(k: Float) 
    
    /**
     * Si se esta escribiendo un texto: entonces las teclas son del texto
     * (Swift se las manda con [`EditorLienzo::teclear`] y
     * [`EditorLienzo::tecla`]) y no atajos.
     */
    func escribiendo()  -> Bool
    
    /**
     * **Cuanto esperar al gesto de pararse** en el trazo de ahora: el medio
     * segundo largo del lapiz o el segundo del grafito. `None` si no se
     * esta trazando a mano (entonces no hay forma rapida). Swift lo pide al
     * pulsar y programa una sola espera, que reprograma cuando el cursor
     * se aleja mas que [`forma_rapida_temblor_px`] y cancela al soltar.
     */
    func esperaFormaMs()  -> UInt64?
    
    /**
     * **El gesto de pararse**: el trazo a mano quieto con el boton pulsado
     * se convierte en compas, rectangulo, linea o elipse
     * (`Gesto::convertir_en_forma`), y lo que se arrastre despues la
     * ajusta. Lo llama Swift cuando vence su espera. `true` si convirtio.
     */
    func formaRapida()  -> Bool
    
    /**
     * **Guarda** el `.excalidraw` como Windows y Android (ver la doc del
     * modulo): las imagenes pegadas que se usan, a `imagenes/` con su
     * entrada en `files`; lo nacido y borrado, con su lapida. Devuelve si
     * escribio algo: sin cambios, o a mitad de un gesto, no escribe.
     * Bloqueante: Swift lo llama fuera del hilo principal.
     */
    func guardar() throws  -> Bool
    
    /**
     * **Cambia de herramienta**: `seleccion` (o `mano`), `lapiz` (o
     * `tinta`), `grafito`, `resaltador`, `rectangulo`, `rombo`, `elipse`,
     * `flecha`, `flecha_codos`, `flecha_libre`, `linea`, `texto`,
     * `borrador` (o `goma`), `lazo`; las de medir `cota`, `escalar` (o
     * `calibrar`) y `escala_grafica`; y las cuatro de construir `relleno`
     * (o `bote`), `recortar`, `extender` y `punto`. Cierra el texto que se
     * estuviera escribiendo.
     */
    func herramienta(nombre: String) throws 
    
    /**
     * La herramienta puesta (los nombres de [`EditorLienzo::herramienta`]).
     */
    func herramientaActual()  -> String
    
    /**
     * Las fotos del lienzo (abierto desde un chat: rutas absolutas; desde
     * un fichero suelto: las relativas del `.excalidraw`).
     */
    func imagenes()  -> [ImagenDelLienzo]
    
    /**
     * Todo el dibujo, sin lo de encima (miniatura, exportar, pruebas).
     */
    func plano()  -> LienzoPlano
    
    /**
     * **Lo que se ve con la camara** en `(x, y)` (el punto del mundo en la
     * esquina de arriba a la izquierda), a `zoom` pixeles por unidad, en una
     * vista de `ancho_px` x `alto_px`; y encima, lo elegido, los tiradores,
     * la marquesina y el cursor del texto. Una llamada por fotograma; la
     * geometria de lo que no cambio sale de la cache.
     */
    func planoDeVista(x: Float, y: Float, zoom: Float, anchoPx: Float, altoPx: Float)  -> LienzoPlano
    
    /**
     * Ver [`EditorLienzo::escala_de_lo_nuevo`]. Dice si cambio algo.
     */
    func ponerAEscala()  -> Bool
    
    /**
     * Si hay algo que deshacer (para la barra).
     */
    func puedeDeshacer()  -> Bool
    
    /**
     * **Un aviso del puntero**, en coordenadas del MUNDO. `presion` es la
     * del lapiz o del Force Touch (0..1), `None` con raton. `modificadores`
     * son bits ([`MOD_MAYUSCULAS`], [`MOD_OPCION`]). `zoom`: pixeles por
     * unidad del mundo, para las tolerancias del motor (que son de
     * pantalla). Devuelve la version: si cambio, hay que repintar.
     */
    func puntero(fase: FasePuntero, x: Float, y: Float, presion: Float?, modificadores: UInt32, zoom: Float)  -> UInt64
    
    func punteroSinEscala(fase: FasePuntero, x: Float, y: Float, presion: Float?, modificadores: UInt32, zoom: Float)  -> UInt64
    
    /**
     * Rehace lo ultimo deshecho.
     */
    func rehacer()  -> Bool
    
    /**
     * El fichero que edita.
     */
    func ruta()  -> String
    
    /**
     * Elige todo lo que se ve.
     */
    func seleccionarTodo() 
    
    /**
     * Si hay cambios sin guardar.
     */
    func sinGuardar()  -> Bool
    
    /**
     * Una tecla de edicion del texto: `izquierda`, `derecha`, `inicio`,
     * `fin`, `retroceso`, `suprimir`, `entrar`; `escape` termina de
     * escribir y deja el texto elegido.
     */
    func tecla(nombre: String)  -> Bool
    
    /**
     * Mete texto en el que se esta escribiendo (lo que da `insertText` de
     * AppKit, ya compuesto: tildes, emoji). `false` si no se escribia.
     */
    func teclear(texto: String)  -> Bool
    
    /**
     * Termina de escribir (un clic fuera, cerrar la ventana). Un texto
     * vacio se quita.
     */
    func terminarTexto()  -> Bool
    
    /**
     * **El color de lo que se dibuja a partir de ahora** (0..1), y el de lo
     * elegido si hay algo elegido. Para la tinta del lector (lapiz y
     * resaltador de colores).
     */
    func tintaColor(r: Float, g: Float, b: Float, a: Float) 
    
    /**
     * **El grosor del lapiz** (`strokeWidth` de Excalidraw: 0,5, 1, 2...).
     */
    func tintaGrosor(grosor: Float) 
    
    /**
     * **Lo que hay que preguntar tras soltar**, una vez: el cajetin de
     * calibrar (`escalar`) o el de la cota recien trazada (`cota`). `None`
     * si nada. Swift lo mira tras cada soltar con esas herramientas.
     */
    func tomarPeticion()  -> PeticionLienzo?
    
    /**
     * Las unidades que se ofrecen al calibrar, de mas a menos uso.
     */
    func unidadesDeMedida()  -> [String]
    
    /**
     * **Sube con todo lo que cambia lo que se ve** (dibujo, lo elegido, el
     * cursor del texto). Swift repinta solo si cambio. Atomico: no espera.
     */
    func version()  -> UInt64
    
    /**
     * **Un mando de la barra**: queda como el estilo de lo proximo y, si
     * hay algo elegido que lo admite, se le aplica en un paso de deshacer.
     * Devuelve si cambio el dibujo (entonces hay que guardar).
     */
    func cambiarEstilo(cambio: CambioDeEstilo)  -> Bool
    
    func cambiarEstiloSinEscala(cambio: CambioDeEstilo)  -> Bool
    
    /**
     * **El estilo que ensena la barra**: el de lo elegido (el primero que
     * siga vivo) o el «actual» con el que nace lo proximo.
     */
    func estilo()  -> EstiloLienzo
    
    /**
     * **Las hojas que salen** al exportar, compartir o imprimir `que`. Vacio
     * si no hay nada (un lienzo en blanco, nada elegido).
     */
    func hojasParaExportar(que: QueExportar)  -> [HojaExportada]
    
    /**
     * **El papel de fondo** del lienzo (un pin, una foto o una pagina de
     * PDF, `fondo_lienzo` de Windows): mide `ancho` x `alto` en el mundo
     * desde (0, 0) y entra en lo exportado; `png` es su imagen para el SVG.
     * Con `ancho` o `alto` a 0 se quita.
     */
    func ponerPapel(ancho: Float, alto: Float, png: Data?) 
    
    /**
     * **Cada hoja de `que` como documento SVG** (el que escribe el motor,
     * el mismo de Windows y del movil), con las fotos dentro. Sin
     * `transparente`, con el papel del lienzo de fondo.
     */
    func svgParaExportar(que: QueExportar, transparente: Bool)  -> [String]
    
    /**
     * **La grafica de una funcion** (una o varias curvas en `formulas`, una
     * por renglon, en funcion de `x`), con sus ejes y su ecuacion, en la
     * ventana `x_desde..x_hasta` x `y_desde..y_hasta` a `escala` pixeles la
     * unidad; con el pincel de ahora, centrada en `(centro_x, centro_y)`.
     */
    func estamparGrafica(formulas: [String], xDesde: Double, xHasta: Double, yDesde: Double, yHasta: Double, escala: Double, centroX: Float, centroY: Float) throws  -> Bool
    
    /**
     * **El instrumento de graficar** con `ejes` ejes: 1 la recta de
     * funciones, 2 el plano y 3 el espacio xyz.
     */
    func estamparInstrumento(ejes: UInt8, centroX: Float, centroY: Float)  -> Bool
    
    /**
     * **Una tabla dibujada** con estas `celdas` (filas de textos; en blanco
     * tambien: una tabla en blanco es donde escribir), la primera fila de
     * cabecera si `cabecera`, con la letra del pincel.
     */
    func estamparTabla(celdas: [[String]], cabecera: Bool, centroX: Float, centroY: Float)  -> Bool
    
    /**
     * **Pega una imagen** (⌘V o soltarla): `png` son los bytes de un PNG
     * (Swift lo codifica con ImageIO, con el lado mayor como mucho
     * [`LADO_MAXIMO`]); entra centrada en `(centro_x, centro_y)` del mundo
     * y reducida si no cabe en el 80 % de lo visible (`ancho_vista` x
     * `alto_vista`, en unidades del mundo). Nace en un paso de deshacer,
     * queda elegida y se pasa a la mano para moverla. Devuelve su
     * `id_objeto` y el fichero de donde pintarla hasta que se guarde.
     */
    func pegarImagen(png: Data, centroX: Float, centroY: Float, anchoVista: Float, altoVista: Float) throws  -> ImagenDelLienzo
    
    /**
     * **La copia de una zona** (F8, `figuras::poner_copia_de_zona` de
     * Windows): `png` es la foto que Swift saco de la caja `(x0, y0, x1,
     * y1)` que pidio [`crate::editor::PeticionLienzo::Zona`], ya recortada
     * en redondo. Entra del tamano de la caja, corrida
     * `zona::CORRIMIENTO_PX` de pantalla (a `zoom`) y elegida, con el grupo
     * que la reconoce como copia de zona. La Zona se queda en la mano: se
     * pueden sacar varias seguidas.
     */
    func ponerCopiaDeZona(png: Data, x0: Float, y0: Float, x1: Float, y1: Float, zoom: Float) throws  -> ImagenDelLienzo
    
    /**
     * **Vuelve a dibujar la tabla elegida con estas celdas** (una fila mas,
     * una columna menos, otro texto), en un paso de deshacer, y deja elegida
     * la nueva. `false` si no hay tabla elegida, si no cambia nada o si las
     * celdas vienen vacias.
     */
    func reemplazarTabla(celdas: [[String]], cabecera: Bool)  -> Bool
    
    /**
     * **La tabla elegida**, si lo elegido es una tabla dibujada (con o sin
     * figuras metidas). `None` si no.
     */
    func tablaElegida()  -> TablaDelLienzo?
    
    /**
     * **Lo que ensena dentro un mosaico o una lupa** cuyo `id_objeto` salio
     * en el plano de la vista (ver la doc del modulo). `None` si ese
     * `id_objeto` es de una foto de verdad o el elemento ya no esta.
     */
    func contenidoDeTapado(idObjeto: UInt64)  -> ContenidoTapado?
    
    /**
     * **El nombre que se propone al guardar lo elegido como figura**: si es
     * una plantilla de serie (una alargada), su nombre con la categoria y
     * un espacio («Planificación · Lista de tareas »), para que caiga en su
     * categoria; si no, vacio (`guardar_seleccion` de Windows).
     */
    func nombrePropuestoDeFigura()  -> String
    
    /**
     * **El enlace cuyo icono esta bajo el punto** `(x, y)` del mundo, con
     * `zoom` pixeles por unidad (el icono mide lo mismo en pantalla a
     * cualquier aumento). `None` si no hay ninguno.
     */
    func enlaceEn(x: Float, y: Float, zoom: Float)  -> String?
    
    /**
     * Los iconos de enlace que caen en la caja `(x0, y0, x1, y1)` del mundo,
     * para pintarlos encima.
     */
    func enlacesEnLaVista(x0: Float, y0: Float, x1: Float, y1: Float)  -> [EnlaceDelLienzo]
    
    /**
     * **La marca con enlace** de una zona mandada al chat: un rectangulo
     * azul a trazos con la caja de la zona, que lleva a `dibujo`. Un paso de
     * deshacer. Devuelve si se puso.
     */
    func marcarZona(x0: Float, y0: Float, x1: Float, y1: Float, dibujo: String)  -> Bool
    
    /**
     * **El iman** de Ajustes → Lienzo (`[enganche]`): a que se pega el
     * cursor al dibujar y a cuantos pixeles de pantalla agarra.
     */
    func ponerIman(activo: Bool, esquinas: Bool, medios: Bool, centros: Bool, radioPx: Float) 
    
}
