/**
 * **Un modelo 3D abierto**, listo para Metal.
 */
public protocol Modelo3dAppleProtocol: AnyObject, Sendable {
    
    /**
     * **La camara de la vista guardada `indice`** (desde 0) en una ventana
     * de `ancho` x `alto` pixeles con `escala` pixeles por punto, como la
     * mira el movil (`croquis::orbita_de` de Windows). `None` si no hay.
     */
    func camaraDeVista(indice: UInt32, ancho: UInt32, alto: UInt32, escala: Double)  -> Camara3d?
    
    /**
     * Las categorias, por su nombre en espanol.
     */
    func categorias()  -> [Categoria3d]
    
    /**
     * La clave estable de un elemento (GlobalId o `~tipo|nombre|k`), la
     * de `aislado_clave` en los marcadores de Windows y Android.
     */
    func claveDeElemento(id: UInt32)  -> String?
    
    /**
     * La clave estable del nivel `k` (`n:=<clave>` en los marcadores).
     */
    func claveDeNivel(k: UInt32)  -> String?
    
    /**
     * **Lo que hay bajo el raton**: el triangulo mas cercano que corta el
     * rayo desde `origen` hacia `direccion` (respecto al origen del modelo;
     * ver [`camara_ojo`] y [`camara_rayo`]), entre lo que se ve con
     * `filtro` y, con caja de seccion, solo dentro de ella.
     */
    func elegir(origen: Punto3d, direccion: Punto3d, filtro: Filtro3d, corte: Caja3d?)  -> Eleccion3d?
    
    /**
     * Lo que se cuenta del elemento `id` (el `elemento` de sus vertices).
     */
    func elemento(id: UInt32)  -> InfoElemento3d?
    
    /**
     * El elemento de esa clave en este modelo.
     */
    func elementoDeClave(clave: String)  -> UInt32?
    
    /**
     * Lo que pide un croquis (ver [`ExtrasCroquis`]); `None` si no lo es.
     */
    func extrasCroquis()  -> ExtrasCroquis?
    
    /**
     * Todos los indices.
     */
    func indices()  -> Indices3d
    
    /**
     * El nivel de esa clave en este modelo.
     */
    func nivelDeClave(clave: String)  -> UInt32?
    
    /**
     * Los niveles, de abajo arriba (vacio si el modelo no los tiene).
     */
    func niveles()  -> [Nivel3d]
    
    func resumen()  -> ResumenModelo3d
    
    /**
     * Los vertices (24 bytes cada uno). Se suben una vez.
     */
    func vertices()  -> Data
    
    /**
     * Los indices de lo que se ve con `filtro`.
     */
    func visibles(filtro: Filtro3d)  -> Indices3d
    
    /**
     * **Los nombres de las vistas guardadas** del croquis (1 a 9, en su
     * orden). Vacio en un modelo de un fichero.
     */
    func vistasGuardadas()  -> [String]
    
}
/**
 * **Un modelo 3D abierto**, listo para Metal.
 */
open class Modelo3dApple: Modelo3dAppleProtocol, @unchecked Sendable {
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noHandle: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing handle the FFI lower functions will crash.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public init(noHandle: NoHandle) {
        self.handle = 0
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public func uniffiCloneHandle() -> UInt64 {
        return try! rustCall { uniffi_pixpin_nucleo_fn_clone_modelo3dapple(self.handle, $0) }
    }
    // No primary constructor declared for this class.

    deinit {
        if handle == 0 {
            // Mock objects have handle=0 don't try to free them
            return
        }

        try! rustCall { uniffi_pixpin_nucleo_fn_free_modelo3dapple(handle, $0) }
    }

    
    /**
     * **Abre un modelo 3D**: IFC, Revit, LandXML, puntos, o un DWG/DXF en
     * 3D. Bloquea (un IFC grande tarda): Swift lo llama desde una `Task`.
     * Leer un IFC usa un hilo aparte con pila grande (sus booleanas
     * recurren hondo), que termina al terminar de leer.
     */
public static func abrir(ruta: String)throws  -> Modelo3dApple  {
    return try  FfiConverterTypeModelo3dApple_lift(try rustCallWithError(FfiConverterTypeErrorNucleo_lift) {
        uniffiCallStatus in
    uniffi_pixpin_nucleo_fn_constructor_modelo3dapple_abrir(
        FfiConverterString.lower(ruta),uniffiCallStatus
    )
})
}
    

    
    /**
     * **La camara de la vista guardada `indice`** (desde 0) en una ventana
     * de `ancho` x `alto` pixeles con `escala` pixeles por punto, como la
     * mira el movil (`croquis::orbita_de` de Windows). `None` si no hay.
     */
open func camaraDeVista(indice: UInt32, ancho: UInt32, alto: UInt32, escala: Double) -> Camara3d?  {
    return try!  FfiConverterOptionTypeCamara3d.lift(try! rustCall() {
        uniffiCallStatus in
    uniffi_pixpin_nucleo_fn_method_modelo3dapple_camara_de_vista(
            self.uniffiCloneHandle(),
        FfiConverterUInt32.lower(indice),
        FfiConverterUInt32.lower(ancho),
        FfiConverterUInt32.lower(alto),
        FfiConverterDouble.lower(escala),uniffiCallStatus
    )
})
}
    
    /**
     * Las categorias, por su nombre en espanol.
     */
open func categorias() -> [Categoria3d]  {
    return try!  FfiConverterSequenceTypeCategoria3d.lift(try! rustCall() {
        uniffiCallStatus in
    uniffi_pixpin_nucleo_fn_method_modelo3dapple_categorias(
            self.uniffiCloneHandle(),uniffiCallStatus
    )
})
}
    
    /**
     * La clave estable de un elemento (GlobalId o `~tipo|nombre|k`), la
     * de `aislado_clave` en los marcadores de Windows y Android.
     */
open func claveDeElemento(id: UInt32) -> String?  {
    return try!  FfiConverterOptionString.lift(try! rustCall() {
        uniffiCallStatus in
    uniffi_pixpin_nucleo_fn_method_modelo3dapple_clave_de_elemento(
            self.uniffiCloneHandle(),
        FfiConverterUInt32.lower(id),uniffiCallStatus
    )
})
}
    
    /**
     * La clave estable del nivel `k` (`n:=<clave>` en los marcadores).
     */
open func claveDeNivel(k: UInt32) -> String?  {
    return try!  FfiConverterOptionString.lift(try! rustCall() {
        uniffiCallStatus in
    uniffi_pixpin_nucleo_fn_method_modelo3dapple_clave_de_nivel(
            self.uniffiCloneHandle(),
        FfiConverterUInt32.lower(k),uniffiCallStatus
    )
})
}
    
    /**
     * **Lo que hay bajo el raton**: el triangulo mas cercano que corta el
     * rayo desde `origen` hacia `direccion` (respecto al origen del modelo;
     * ver [`camara_ojo`] y [`camara_rayo`]), entre lo que se ve con
     * `filtro` y, con caja de seccion, solo dentro de ella.
     */
open func elegir(origen: Punto3d, direccion: Punto3d, filtro: Filtro3d, corte: Caja3d?) -> Eleccion3d?  {
    return try!  FfiConverterOptionTypeEleccion3d.lift(try! rustCall() {
        uniffiCallStatus in
    uniffi_pixpin_nucleo_fn_method_modelo3dapple_elegir(
            self.uniffiCloneHandle(),
        FfiConverterTypePunto3d_lower(origen),
        FfiConverterTypePunto3d_lower(direccion),
        FfiConverterTypeFiltro3d_lower(filtro),
        FfiConverterOptionTypeCaja3d.lower(corte),uniffiCallStatus
    )
})
}
    
    /**
     * Lo que se cuenta del elemento `id` (el `elemento` de sus vertices).
     */
open func elemento(id: UInt32) -> InfoElemento3d?  {
    return try!  FfiConverterOptionTypeInfoElemento3d.lift(try! rustCall() {
        uniffiCallStatus in
    uniffi_pixpin_nucleo_fn_method_modelo3dapple_elemento(
            self.uniffiCloneHandle(),
        FfiConverterUInt32.lower(id),uniffiCallStatus
    )
})
}
    
    /**
     * El elemento de esa clave en este modelo.
     */
open func elementoDeClave(clave: String) -> UInt32?  {
    return try!  FfiConverterOptionUInt32.lift(try! rustCall() {
        uniffiCallStatus in
    uniffi_pixpin_nucleo_fn_method_modelo3dapple_elemento_de_clave(
            self.uniffiCloneHandle(),
        FfiConverterString.lower(clave),uniffiCallStatus
    )
})
}
    
    /**
     * Lo que pide un croquis (ver [`ExtrasCroquis`]); `None` si no lo es.
     */
open func extrasCroquis() -> ExtrasCroquis?  {
    return try!  FfiConverterOptionTypeExtrasCroquis.lift(try! rustCall() {
        uniffiCallStatus in
    uniffi_pixpin_nucleo_fn_method_modelo3dapple_extras_croquis(
            self.uniffiCloneHandle(),uniffiCallStatus
    )
})
}
    
    /**
     * Todos los indices.
     */
open func indices() -> Indices3d  {
    return try!  FfiConverterTypeIndices3d_lift(try! rustCall() {
        uniffiCallStatus in
    uniffi_pixpin_nucleo_fn_method_modelo3dapple_indices(
            self.uniffiCloneHandle(),uniffiCallStatus
    )
})
}
    
    /**
     * El nivel de esa clave en este modelo.
     */
open func nivelDeClave(clave: String) -> UInt32?  {
    return try!  FfiConverterOptionUInt32.lift(try! rustCall() {
        uniffiCallStatus in
    uniffi_pixpin_nucleo_fn_method_modelo3dapple_nivel_de_clave(
            self.uniffiCloneHandle(),
        FfiConverterString.lower(clave),uniffiCallStatus
    )
})
}
    
    /**
     * Los niveles, de abajo arriba (vacio si el modelo no los tiene).
     */
open func niveles() -> [Nivel3d]  {
    return try!  FfiConverterSequenceTypeNivel3d.lift(try! rustCall() {
        uniffiCallStatus in
    uniffi_pixpin_nucleo_fn_method_modelo3dapple_niveles(
            self.uniffiCloneHandle(),uniffiCallStatus
    )
})
}
    
open func resumen() -> ResumenModelo3d  {
    return try!  FfiConverterTypeResumenModelo3d_lift(try! rustCall() {
        uniffiCallStatus in
    uniffi_pixpin_nucleo_fn_method_modelo3dapple_resumen(
            self.uniffiCloneHandle(),uniffiCallStatus
    )
})
}
    
    /**
     * Los vertices (24 bytes cada uno). Se suben una vez.
     */
open func vertices() -> Data  {
    return try!  FfiConverterData.lift(try! rustCall() {
        uniffiCallStatus in
    uniffi_pixpin_nucleo_fn_method_modelo3dapple_vertices(
            self.uniffiCloneHandle(),uniffiCallStatus
    )
})
}
    
    /**
     * Los indices de lo que se ve con `filtro`.
     */
open func visibles(filtro: Filtro3d) -> Indices3d  {
    return try!  FfiConverterTypeIndices3d_lift(try! rustCall() {
        uniffiCallStatus in
    uniffi_pixpin_nucleo_fn_method_modelo3dapple_visibles(
            self.uniffiCloneHandle(),
        FfiConverterTypeFiltro3d_lower(filtro),uniffiCallStatus
    )
})
}
    
    /**
     * **Los nombres de las vistas guardadas** del croquis (1 a 9, en su
     * orden). Vacio en un modelo de un fichero.
     */
open func vistasGuardadas() -> [String]  {
    return try!  FfiConverterSequenceString.lift(try! rustCall() {
        uniffiCallStatus in
    uniffi_pixpin_nucleo_fn_method_modelo3dapple_vistas_guardadas(
            self.uniffiCloneHandle(),uniffiCallStatus
    )
})
}
    

    
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeModelo3dApple: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = Modelo3dApple

    public static func lift(_ handle: UInt64) throws -> Modelo3dApple {
        return Modelo3dApple(unsafeFromHandle: handle)
    }

    public static func lower(_ value: Modelo3dApple) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Modelo3dApple {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: Modelo3dApple, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeModelo3dApple_lift(_ handle: UInt64) throws -> Modelo3dApple {
    return try FfiConverterTypeModelo3dApple.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeModelo3dApple_lower(_ value: Modelo3dApple) -> UInt64 {
    return FfiConverterTypeModelo3dApple.lower(value)
}






/**
 * **Una carpeta de datos de PixPin abierta**: el objeto con el que trabaja
 * Swift. Es barato de crear y se puede usar desde varios hilos.
 */
public protocol NucleoProtocol: AnyObject, Sendable {
    
    /**
     * Quien es este aparato y en que grupo esta.
     */
    func aparato() throws  -> InfoAparato
    
    /**
     * La carpeta de datos.
     */
    func raiz()  -> String
    
    /**
     * Suelta las caches (indices de los cuadernos). Para el aviso de
     * memoria del sistema (`didReceiveMemoryWarning`,
     * `DispatchSource.makeMemoryPressureSource`): se rehacen solas al
     * volver a leer.
     */
    func vaciarCaches() 
    
    /**
     * **Adjunta un fichero a un chat**: lo copia dentro del proyecto y
     * escribe su mensaje (`IMAGEN` si es una foto, `VOZ` si es audio,
     * `ARCHIVO` lo demas), como al soltarlo en el chat de Windows.
     *
     * `nombre` es el que se ensena y con el que se guarda; sin el, el del
     * fichero de origen. Es bloqueante (copia el fichero): Swift lo llama
     * fuera del hilo principal.
     */
    func adjuntar(chat: String, rutaOrigen: String, nombre: String?) throws  -> MensajeChat
    
    /**
     * **Adjunta un proyecto entero** al chat `chat` (la hoja «+» de
     * Windows, `AdjProyecto`): no se copia, es la puerta a lo que ya existe
     * (un mensaje `PROYECTO` con `referencia` = el id del otro chat).
     */
    func adjuntarProyecto(chat: String, proyecto: String) throws  -> MensajeChat
    
    /**
     * Las fotos de un lienzo del chat con su ruta **absoluta**, todas en
     * una llamada (no una por foto). Las que no se pueden resolver en este
     * aparato no salen.
     */
    func imagenesDelLienzo(chat: String, lienzo: Lienzo) throws  -> [ImagenDelLienzo]
    
    /**
     * La ruta absoluta del fichero de un mensaje (su `ruta`) o de una foto
     * de un lienzo, para ensenarlo o abrirlo. No comprueba que exista:
     * para eso basta mirar el disco desde Swift.
     */
    func rutaAbsoluta(chat: String, rutaRelativa: String) throws  -> String
    
    /**
     * Los ajustes de `pixpinmax.toml` (los de fabrica si no hay fichero).
     */
    func ajustes() throws  -> AjustesMac
    
    /**
     * Los de fabrica, los de Windows (para el punto azul de «cambiado» y
     * «Restablecer» de la pantalla de Ajustes).
     */
    func ajustesDeFabrica()  -> AjustesMac
    
    /**
     * Guarda los ajustes del Mac en `pixpinmax.toml` sin tocar lo demas.
     */
    func guardarAjustes(nuevos: AjustesMac) throws 
    
    /**
     * La ruta de `pixpinmax.toml` (para ensenarla).
     */
    func rutaAjustes()  -> String
    
    /**
     * Tareas, Lienzo y Pinear de `pixpinmax.toml` (los de fabrica si no
     * hay fichero). De paso fija las palabras de urgencia con que se
     * entienden las tareas.
     */
    func ajustesOrganizar() throws  -> AjustesOrganizar
    
    /**
     * Los de fabrica, los de Windows.
     */
    func ajustesOrganizarDeFabrica()  -> AjustesOrganizar
    
    /**
     * Guarda Tareas, Lienzo y Pinear sin tocar lo demas del fichero, y
     * fija las palabras de urgencia nuevas.
     */
    func guardarAjustesOrganizar(nuevos: AjustesOrganizar) throws 
    
    /**
     * **La herramienta que abre `texto` pineado** con las palabras magicas
     * de Ajustes → Pinear (`TIMER`, `CHECKLIST`, `DRAW`…), o `None` si es
     * texto corriente o el fichero no se lee.
     */
    func palabraMagicaDe(texto: String)  -> String?
    
    /**
     * Los ajustes `[pdf]` de `pixpinmax.toml`.
     */
    func ajustesPdf() throws  -> AjustesPdf
    
    /**
     * **Aligera un PDF del chat en su sitio** (`ruta`: la de
     * [`Nucleo::ruta_absoluta`]), como Windows. `a_mano`: pedido desde el
     * menu del mensaje (se repite aunque ya se hubiera pasado). Bloqueante.
     */
    func aligerarEnSuSitio(ruta: String, nivel: NivelAligerar, aMano: Bool, avance: AvanceAligerar)  -> DesenlaceAligerar
    
    /**
     * Guarda `[pdf]` sin tocar lo demas del fichero.
     */
    func guardarAjustesPdf(nuevos: AjustesPdf) throws 
    
    /**
     * **Manda a Anki** las tarjetas del mensaje `mensaje` de `chat`, como
     * `anki::enviar` de Windows. `pregunta_de_la_clase` es el texto de
     * delante de cada captura (`anki-pregunta-clase`). Bloqueante: lee el
     * cuaderno y habla con Anki por `127.0.0.1`.
     */
    func enviarAAnki(chat: String, mensaje: String, preguntaDeLaClase: String) throws  -> EnvioAnki
    
    /**
     * **Guarda una pantalla anotada en «Mensajes guardados»** (creandolo si
     * no esta): `foto` es el PNG de lo que habia debajo; la tinta es la del
     * `editor` del anotador, que empieza en `origen_x, origen_y` (puntos del
     * escritorio) y lleva `escala` pixeles de la foto por punto. Bloqueante
     * (copia la foto y escribe el lienzo): Swift lo llama fuera del hilo
     * principal.
     */
    func pantallaAnotadaAlChat(foto: String, editor: EditorLienzo, origenX: Float, origenY: Float, escala: Float) throws  -> PantallaAnotada
    
    /**
     * **Pone al dia el lienzo de una pantalla ya guardada** en esta sesion
     * con la tinta de ahora: ni foto nueva ni mensaje nuevo (la de fondo es
     * la de la primera vez, sobre la que se dibujo). Lo de antes se marca
     * borrado, que es lo que le dice al movil «esto se quito». Devuelve
     * cuantos trazos quedaron. Sin el lienzo, error: no se inventa uno sin
     * foto. Bloqueante.
     */
    func ponerAlDiaPantallaAnotada(guardada: PantallaAnotada, editor: EditorLienzo, origenX: Float, origenY: Float, escala: Float) throws  -> UInt32
    
    /**
     * **Apunta donde esta** el aparato `id` (lo que da la sonda de un
     * aparato visto en Bonjour, o la direccion nueva de [`donde_esta`]).
     */
    func apuntarDireccion(id: String, host: String, puerto: UInt16) throws  -> Bool
    
    /**
     * Las direcciones recordadas (`sincro/direcciones.txt`).
     */
    func direccionesRecordadas()  -> [DireccionRecordada]
    
    /**
     * **Los miembros del grupo menos este**, por nombre, con su direccion
     * recordada y la ultima vez que se sincronizo con cada uno. Sin grupo,
     * ninguno.
     */
    func miembrosDelGrupo() throws  -> [MiembroGrupo]
    
    /**
     * **Olvida la direccion recordada** del aparato `id` (la quita de
     * `sincro/direcciones.txt`). `false` si no habia ninguna.
     */
    func olvidarDireccion(id: String) throws  -> Bool
    
    /**
     * **Renombra este aparato** (`Disco.renombrar`): tambien en su ficha
     * de miembro, que es lo que ven los demas en la siguiente vuelta. Sin
     * blancos alrededor y con el tope del movil (40); vacio no vale.
     */
    func renombrarAparato(nombre: String) throws  -> InfoAparato
    
    /**
     * **Sale del grupo** (`Disco.salirDelGrupo`): sin codigo, sin miembros
     * y sin letra, y se olvida lo acordado con los demas (`sincro/base/`).
     * No se borra ningun chat. Si vuelve a unirse, la primera vez
     * preguntara por lo que haya cambiado en los dos lados.
     */
    func salirDelGrupo() throws  -> InfoAparato
    
    /**
     * **La sonda `PING`/`PONG`** a una direccion escrita o recordada.
     * Bloquea hasta unos 3 s como mucho.
     */
    func sondearDireccion(host: String, puerto: UInt16)  -> Bool
    
    /**
     * **Lo que quedo a medias la ultima vez** que se cerro PixPin con el
     * asistente trabajando: cada burbuja cortada dice que paso y, lo que se
     * puede, nace otra vez debajo para que Swift lo lance. Se llama una vez
     * al arrancar, fuera del hilo principal (mira el motor de `ajustes`).
     */
    func iaRetomarAlArrancar(ajustes: AjustesIa)  -> [RetomadoIa]
    
    /**
     * **El chat «Asistente»**, creandolo si no esta (como «Mensajes
     * guardados»: fijo, detras de el en la lista).
     *
     * **Uno solo en todos los aparatos** (Windows, 22-oct): antes de mirar
     * si hay que crearlo se juntan los que hayan llegado de otros aparatos
     * ([`Nucleo::unificar_asistentes`]); el que queda lleva la marca
     * (`"asistente": true`, que viaja en `proyecto.json`).
     */
    func chatAsistente() throws  -> FichaChat
    
    /**
     * **Despues de escribir un mensaje** (`mensaje`, una nota o una foto):
     * si es para el asistente (el chat «Asistente», o `@asistente` en otro)
     * nace su respuesta, con «💭 Pensando…», y se devuelve para lanzar el
     * turno ([`ia_turno_en_chat`]). `None` si no era para el.
     */
    func iaAlEnviar(chat: String, mensaje: String) throws  -> InicioIa?
    
    /**
     * **«Conversación nueva»** en el chat `chat`: una nota del asistente que
     * corta el contexto que se le manda (lo de antes sigue a la vista y
     * viaja como siempre; Windows, 17-oct).
     */
    func iaConversacionNueva(chat: String) throws  -> MensajeChat
    
    /**
     * **Un boton de la tarjeta de opciones** de la respuesta `nota`:
     * `Some(n)`, la opcion `n` (desde 0); `None`, «Otro…» (lo siguiente que
     * se escriba es la respuesta). `false` si ya no esperaba nada.
     */
    func iaElegir(chat: String, nota: String, opcion: UInt32?)  -> Bool
    
    /**
     * **Lo escrito mientras el asistente trabaja** en `chat` (Windows,
     * 25-oct-2026, «como en Claude Code»): si hay una duda con opciones
     * esperando y el mensaje es para el (o se pulso «Otro…»), es su
     * respuesta; si no, y es para el, va al turno en marcha, que lo lee
     * antes de su siguiente paso y corrige, anade o para («para» a secas lo
     * corta). `false` si no habia turno en marcha que lo recoja (Swift dice
     * entonces que esta ocupado).
     */
    func iaEscribirMientrasTrabaja(chat: String, mensaje: String)  -> Bool
    
    /**
     * **La lista de `@`** para lo escrito tras el `@`: el asistente (fuera
     * de su chat) y los lienzos y hojas de la conversacion, del mas nuevo
     * al mas viejo.
     */
    func iaOpcionesMencion(chat: String, escrito: String)  -> [OpcionMencionIa]
    
    /**
     * **Lo que se pinta encima de una respuesta guardada**: lo que penso,
     * la peticion mejorada y si se renovo el contexto. `None` si no es del
     * asistente o no hay nada que ensenar.
     */
    func iaPensado(chat: String, nota: String)  -> PensadoIa?
    
    /**
     * **Escribe la respuesta acabada** que no salio de [`ia_turno_en_chat`]
     * (Apple Intelligence, o un aviso): el texto y, si dibujo, `lienzo` (un
     * `.excalidraw`) al lienzo del chat, apuntado para su «Abrir lienzo».
     */
    func iaResponder(chat: String, nota: String, texto: String, lienzo: String?) throws  -> MensajeChat
    
    /**
     * **La carpeta de la memoria del asistente** (la franja del chat
     * «Asistente» de Windows: ahi el usuario la lee y la cambia con
     * cualquier editor), creandola si no esta.
     */
    func iaCarpetaDeMemoria() throws  -> String
    
    /**
     * La quita (de la fila y de las automatizaciones: es la misma).
     */
    func iaRecetaBorrar(id: String) throws 
    
    /**
     * Cambia el nombre, el icono y el pedido de una.
     */
    func iaRecetaCambiar(id: String, nombre: String, icono: String, pedido: String) throws 
    
    /**
     * **«Guardar como receta»** desde un mensaje del chat: el de una
     * pregunta, su texto; el de una respuesta del asistente, la pregunta
     * que contesta (la que cuelga, o la ultima nota del usuario de antes).
     * Sin la mencion `@asistente`. `None` si no hay nada que pedir.
     */
    func iaRecetaDesde(chat: String, mensaje: String) throws  -> RecetaIa?
    
    /**
     * La mueve `paso` sitios en la fila (−1: a la izquierda).
     */
    func iaRecetaMover(id: String, paso: Int32) throws 
    
    /**
     * Una receta nueva al final de la fila. Sin nombre, el principio del
     * pedido; sin icono, uno segun lo que pide.
     */
    func iaRecetaNueva(nombre: String, icono: String, pedido: String) throws  -> RecetaIa
    
