        self.nombre = nombre
        self.aqui = aqui
        self.alli = alli
        self.estadoAqui = estadoAqui
        self.recienteAqui = recienteAqui
        self.estadoAlli = estadoAlli
        self.recienteAlli = recienteAlli
        self.marcado = marcado
        self.seBorraAqui = seBorraAqui
    }

    

    
}

