    public var nombreChat: String
    /**
     * El id del mensaje (en mensajes y tareas).
     */
    public var mensaje: String?
    /**
     * La posicion del mensaje en su chat (0 el mas antiguo), la de
     * [`Nucleo::mensajes`].
     */
    public var posicion: UInt64?
    /**
     * El numero de la tarea en su lista.
     */
    public var tarea: UInt32?
    public var hecha: Bool
    /**
     * El id del momento.
     */
    public var momento: String?
    /**
     * La clase del mensaje (`NOTA`, `IMAGEN`...) o vacio.
     */
    public var tipo: String
    /**
     * La linea principal: el nombre del chat, el del fichero, el titulo
     * de la lista o del momento.
     */
    public var titulo: String
    /**
     * Un trozo del texto donde esta lo buscado.
     */
    public var fragmento: String
    /**
     * Milisegundos desde 1970.
     */
    public var cuando: Int64
    /**
     * Lo que lo identifica entre todos (`captura/<nombre>`,
     * `mensaje/<chat>/<id>`...), como la `recordKey` de Windows.
     */
    public var clave: String
    /**
     * La ruta absoluta del fichero en este aparato (un fichero, una
     * captura, la primera foto de un momento), si se resuelve.
     */
    public var ruta: String?
    /**
     * El id de la leccion.
     */
    public var leccion: String?
    /**
     * Cuanto vale la coincidencia (`puntos::puntuar`); 0 sin consulta.
     */
    public var puntos: UInt32
    /**
     * Las letras de `titulo` que coinciden, en UTF-16 (`NSString`).
     */
    public var resaltado: [UInt32]
    /**
     * Se encontro dentro (el texto del documento o el leido de la
     * captura), no en el nombre.
     */
    public var dentro: Bool
    /**
     * El tamano del fichero o la captura.
     */
    public var bytes: UInt64
    /**
     * Una captura conservada (no caduca).
     */
    public var conservada: Bool
    /**
     * Los dias que le quedan a una captura (0: hoy); `None` si no se va.
     */
    public var diasQueQuedan: Int64?
    /**
     * El texto de la tarea tal cual esta en su lista (lo que pide
     * [`Nucleo::marcar_tarea`]); vacio en lo demas.
     */
    public var crudo: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(clase: ClaseDeResultado, 
        /**
         * El chat (no en los momentos).
         */chat: String?, nombreChat: String, 
        /**
         * El id del mensaje (en mensajes y tareas).
         */mensaje: String?, 
        /**
         * La posicion del mensaje en su chat (0 el mas antiguo), la de
         * [`Nucleo::mensajes`].
         */posicion: UInt64?, 
        /**
         * El numero de la tarea en su lista.
         */tarea: UInt32?, hecha: Bool, 
        /**
         * El id del momento.
         */momento: String?, 
        /**
         * La clase del mensaje (`NOTA`, `IMAGEN`...) o vacio.
         */tipo: String, 
        /**
         * La linea principal: el nombre del chat, el del fichero, el titulo
         * de la lista o del momento.
         */titulo: String, 
        /**
         * Un trozo del texto donde esta lo buscado.
         */fragmento: String, 
        /**
         * Milisegundos desde 1970.
         */cuando: Int64, 
        /**
         * Lo que lo identifica entre todos (`captura/<nombre>`,
         * `mensaje/<chat>/<id>`...), como la `recordKey` de Windows.
         */clave: String, 
        /**
         * La ruta absoluta del fichero en este aparato (un fichero, una
         * captura, la primera foto de un momento), si se resuelve.
         */ruta: String?, 
        /**
         * El id de la leccion.
         */leccion: String?, 
        /**
         * Cuanto vale la coincidencia (`puntos::puntuar`); 0 sin consulta.
         */puntos: UInt32, 
        /**
         * Las letras de `titulo` que coinciden, en UTF-16 (`NSString`).
         */resaltado: [UInt32], 
        /**
         * Se encontro dentro (el texto del documento o el leido de la
         * captura), no en el nombre.
         */dentro: Bool, 
        /**
         * El tamano del fichero o la captura.
         */bytes: UInt64, 
        /**
         * Una captura conservada (no caduca).
         */conservada: Bool, 
        /**
         * Los dias que le quedan a una captura (0: hoy); `None` si no se va.
         */diasQueQuedan: Int64?, 
        /**
         * El texto de la tarea tal cual esta en su lista (lo que pide
         * [`Nucleo::marcar_tarea`]); vacio en lo demas.
         */crudo: String) {
        self.clase = clase
        self.chat = chat
        self.nombreChat = nombreChat
        self.mensaje = mensaje
        self.posicion = posicion
        self.tarea = tarea
        self.hecha = hecha
        self.momento = momento
        self.tipo = tipo
        self.titulo = titulo
        self.fragmento = fragmento
        self.cuando = cuando
        self.clave = clave
        self.ruta = ruta
        self.leccion = leccion
        self.puntos = puntos
        self.resaltado = resaltado
        self.dentro = dentro
        self.bytes = bytes
        self.conservada = conservada
        self.diasQueQuedan = diasQueQuedan
        self.crudo = crudo
    }

    

    
}

